+<script>
+'use strict';
+const gridEl = document.getElementById('grid');
+const statusEl = document.getElementById('status');
+const visitedCountEl = document.getElementById('visitedCount');
+const pathLengthEl = document.getElementById('pathLength');
+const pathCostEl = document.getElementById('pathCost');
+const elapsedEl = document.getElementById('elapsed');
+const compareWrap = document.getElementById('compareWrap');
+
+const MUD_COST = 5;
+let ROWS = 25, COLS = 25;
+let start = [Math.floor(ROWS/2), 3];
+let end = [Math.floor(ROWS/2), COLS - 4];
+let grid = []; // 0 open, 1 wall
+let weights = []; // per-cell cost, default 1, mud = MUD_COST
+let cellEls = [];
+let mouseDown = false;
+let dragging = null; // 'start' | 'end' | 'wall' | 'mud'
+let running = false;
+
+function buildGrid() {
+  grid = Array.from({length: ROWS}, () => Array(COLS).fill(0));
+  weights = Array.from({length: ROWS}, () => Array(COLS).fill(1));
+  gridEl.style.gridTemplateColumns = `repeat(${COLS}, 22px)`;
+  gridEl.innerHTML = '';
+  cellEls = [];
+  for (let r = 0; r < ROWS; r++) {
+    const row = [];
+    for (let c = 0; c < COLS; c++) {
+      const div = document.createElement('div');
+      div.className = 'cell';
+      div.dataset.r = r; div.dataset.c = c;
+      div.addEventListener('mousedown', (e) => { e.preventDefault(); onCellDown(r, c, e.button === 2 || e.shiftKey); });
+      div.addEventListener('contextmenu', (e) => e.preventDefault());
+      div.addEventListener('mouseenter', () => onCellEnter(r, c));
+      gridEl.appendChild(div);
+      row.push(div);
+    }
+    cellEls.push(row);
+  }
