+function onCellEnter(r, c) {
+  if (!mouseDown || running) return;
+  if (dragging === 'start') { if (grid[r][c] !== 1 && !(r===end[0]&&c===end[1])) { start = [r, c]; render(); } return; }
+  if (dragging === 'end') { if (grid[r][c] !== 1 && !(r===start[0]&&c===start[1])) { end = [r, c]; render(); } return; }
+  if (dragging === 'mud') { paintMud(r, c); return; }
+  if (dragging === 'wall') {
+    if (!(r===start[0]&&c===start[1]) && !(r===end[0]&&c===end[1])) {
+      grid[r][c] = 1;
+      weights[r][c] = 1;
+      cellEls[r][c].className = 'cell wall';
+    }
+  }
+}
+function paintMud(r, c) {
+  if (r===start[0]&&c===start[1]) return;
+  if (r===end[0]&&c===end[1]) return;
+  if (grid[r][c] === 1) return;
+  weights[r][c] = weights[r][c] > 1 ? 1 : MUD_COST;
+  render();
+}
+function toggleWall(r, c) {
+  if (r===start[0]&&c===start[1]) return;
+  if (r===end[0]&&c===end[1]) return;
+  grid[r][c] = grid[r][c] === 1 ? 0 : 1;
+  render();
+}
+document.addEventListener('mouseup', () => { mouseDown = false; dragging = null; });
+
+function clearVisualState() {
+  for (let r = 0; r < ROWS; r++) for (let c = 0; c < COLS; c++) {
+    cellEls[r][c].classList.remove('visited', 'frontier', 'path');
+  }
+}
+
+function sleep(ms) { return new Promise(res => setTimeout(res, ms)); }
+
+async function visualize() {
+  if (running) return;
+  running = true;
+  document.getElementById('run').disabled = true;
+  clearVisualState();
+  statusEl.textContent = 'Running…';
+  visitedCountEl.textContent = '0';
+  pathLengthEl.textContent = '–';
+  elapsedEl.textContent = '–';
+
+  const algoName = document.getElementById('algo').value;
+  const fn = window.PF[algoName];
+  const t0 = performance.now();
+  const result = (algoName === 'dijkstra' || algoName === 'astar') ? fn(grid, start, end, weights) : fn(grid, start, end);
+  const t1 = performance.now();
+
+  const speed = Number(document.getElementById('speed').value);
+  const baseDelay = Math.max(1, 22 - speed * 2);
+  const batch = speed >= 8 ? 3 : 1;
+
+  for (let i = 0; i < result.visitedOrder.length; i += batch) {
+    for (let j = i; j < Math.min(i + batch, result.visitedOrder.length); j++) {
+      const [r, c] = result.visitedOrder[j].split(',').map(Number);
+      if (!(r===start[0]&&c===start[1]) && !(r===end[0]&&c===end[1])) {
+        cellEls[r][c].classList.add('visited');
+      }
+    }
+    visitedCountEl.textContent = String(Math.min(i + batch, result.visitedOrder.length));
+    await sleep(baseDelay);
+  }
+
+  if (result.found) {
+    for (const k of result.path) {
+      const [r, c] = k.split(',').map(Number);
+      if (!(r===start[0]&&c===start[1]) && !(r===end[0]&&c===end[1])) {
+        cellEls[r][c].classList.add('path');
+      }
+      await sleep(baseDelay / 2);
+    }
+    statusEl.textContent = 'Path found ✅';
+    pathLengthEl.textContent = String(result.path.length - 1) + ' steps';
+    pathCostEl.textContent = result.cost !== undefined ? String(result.cost) : String(result.path.length - 1);
+  } else {
+    statusEl.textContent = 'No path exists ❌';
+    pathLengthEl.textContent = 'n/a';
+    pathCostEl.textContent = 'n/a';
+  }
+  elapsedEl.textContent = (t1 - t0).toFixed(2) + ' ms';
+  running = false;
+  document.getElementById('run').disabled = false;
+}
+
+function runCompare() {
+  if (running) return;
+  compareWrap.style.display = 'block';
+  const names = { bfs: 'BFS', dfs: 'DFS', dijkstra: 'Dijkstra', astar: 'A*' };
+  const rows = [];
+  for (const key of ['bfs', 'dfs', 'dijkstra', 'astar']) {
+    const fn = window.PF[key];
+    const usesWeights = key === 'dijkstra' || key === 'astar';
+    const t0 = performance.now();
+    const r = usesWeights ? fn(grid, start, end, weights) : fn(grid, start, end);
+    const t1 = performance.now();
+    rows.push({
+      name: names[key],
+      found: r.found,
+      visited: r.visitedOrder.length,
+      steps: r.found ? r.path.length - 1 : '–',
+      cost: r.found ? (r.cost !== undefined ? r.cost : r.path.length - 1) : '–',
+      time: (t1 - t0).toFixed(2),
+    });
+  }
+  const minVisited = Math.min(...rows.filter(r => r.found).map(r => r.visited));
+  const minCost = Math.min(...rows.filter(r => r.found && typeof r.cost === 'number').map(r => r.cost));
+  let html = '<table id="compareTable"><thead><tr><th>Algorithm</th><th>Found?</th><th>Nodes visited</th><th>Path steps</th><th>Path cost</th><th>Time (ms)</th></tr></thead><tbody>';
+  for (const r of rows) {
+    html += `<tr><td>${r.name}</td><td>${r.found ? '✅' : '❌'}</td>` +
+      `<td${r.visited === minVisited ? ' class="best"' : ''}>${r.visited}</td>` +
+      `<td>${r.steps}</td>` +
+      `<td${r.cost === minCost ? ' class="best"' : ''}>${r.cost}</td>` +
