+        (r === end[0] && c === end[1] ? ' end' : '');
+    }
+  }
+}
+
+function onCellDown(r, c, wantMud) {
+  if (running) return;
+  mouseDown = true;
+  if (r === start[0] && c === start[1]) { dragging = 'start'; return; }
+  if (r === end[0] && c === end[1]) { dragging = 'end'; return; }
