// Recursive-backtracker maze generator on an odd-sized grid.
// Returns a rows x cols grid of 0 (passage) / 1 (wall).
function generateMaze(rows, cols, rng) {
  rng = rng || Math.random;
  const grid = Array.from({ length: rows }, () => Array(cols).fill(1));
  function carve(r, c) {
