+    <span><span class="swatch" style="background:var(--end)"></span> End (drag me)</span>
+    <span><span class="swatch" style="background:var(--wall)"></span> Wall (click/drag to draw)</span>
+    <span><span class="swatch" style="background:#6b4a2b"></span> Mud, cost 5 (right-click/shift-click to draw)</span>
+    <span><span class="swatch" style="background:var(--visited)"></span> Visited</span>
