+    dfs: typeof dfs !== 'undefined' ? dfs : null,
+    dijkstra: typeof dijkstra !== 'undefined' ? dijkstra : null,
+    astar: typeof astar !== 'undefined' ? astar : null,
+    bidirectionalBFS: typeof bidirectionalBFS !== 'undefined' ? bidirectionalBFS : null,
+    generateMaze: typeof generateMaze !== 'undefined' ? generateMaze : null,
+  };
